<?php

declare(strict_types=1);

namespace App\Domains\Compliance\Countries\SaudiArabia\Issuing;

use App\Domains\Compliance\Countries\SaudiArabia\Onboarding\EnvironmentSwitch;
use App\Domains\Invoice\Models\Invoice;
use App\Domains\Organization\Models\Organization;
use Carbon\CarbonImmutable;

/**
 * Where a device's chain starts again: at each ZATCA environment.
 *
 * ZATCA chains the documents of one EGS unit (Detailed Guidelines: "all
 * invoices generated by an E-Invoice Solution Unit are linked using
 * 'Previous Invoice Hash' value into a single chain"), and each environment
 * onboards the device afresh with its own CSID - a new unit there. Its first
 * document in the new environment therefore carries the genesis PIH
 * (BR-KSA-26: "For the first invoice, the previous invoice hash is
 * NWZlY2Vi...") rather than the hash of a sandbox or simulation document the
 * new environment never received.
 *
 * The counter is not reset: "The E-Invoice Solution must not provide a
 * feature where the invoice counting can be reset" (Detailed Guidelines,
 * anti-tampering), and ZATCA asks only that it be digits (BR-KSA-33, 34).
 * The old chain is kept as it was, every entry, for audit.
 *
 * A switch is refused while anything signed in the old environment is
 * unfiled (EnvironmentSwitch::waiting), so every document issued after it
 * belongs to the new environment.
 */
final class ChainStart
{
    /**
     * The PIH this document carries: its device's previous document's hash,
     * or null - the genesis PIH - when it is the device's first, or the first
     * since its organization changed ZATCA environment.
     */
    public function previousHash(Invoice $invoice): ?string
    {
        if ($invoice->icv === null) {
            return null;
        }

        $previous = Invoice::withoutTenantScope(fn (): ?Invoice => Invoice::query()
            ->where('org_id', $invoice->org_id)
            ->where('device_id', $invoice->device_id ?? $invoice->org_id)
            ->where('icv', '<', $invoice->icv)
            ->whereNotNull('hash')
            ->orderByDesc('icv')
            ->first(['id', 'hash', 'issued_at', 'created_at']));

        if ($previous === null) {
            return null;
        }

        $since = $invoice->org?->compliance_profile[EnvironmentSwitch::SINCE_KEY] ?? null;

        return $since !== null && $this->issuedAt($previous)->lt(CarbonImmutable::parse($since))
            ? null
            : $previous->hash;
    }

    /**
     * Whether the organization changed ZATCA environment between these two
     * moments: a document after it starts a chain. Every switch is kept
     * (EnvironmentSwitch::SWITCHES_KEY), so a chain several environments old
     * checks too.
     */
    public function switchedBetween(Organization $organization, CarbonImmutable $after, CarbonImmutable $until): bool
    {
        $profile = $organization->compliance_profile ?? [];
        $moments = [...(array) ($profile[EnvironmentSwitch::SWITCHES_KEY] ?? []), $profile[EnvironmentSwitch::SINCE_KEY] ?? null];

        foreach (array_filter($moments) as $moment) {
            $at = CarbonImmutable::parse((string) $moment);

            if ($at->gte($after) && $at->lte($until)) {
                return true;
            }
        }

        return false;
    }

    public function issuedAt(Invoice $invoice): CarbonImmutable
    {
        return CarbonImmutable::parse($invoice->issued_at ?? $invoice->created_at);
    }
}
